// Des: Page snapshot by accessibility tree, find by name
// Flo: enable AX > getFullAXTree > parse nodes > find by role + name > scroll + box center
// I/O: CDP Conn (caller) > Node list, Pt click point, evaluated page text
// ===================================================================
const std = @import("std"); const cdp = @import("nt-cdpz-sock.zig");
const CF = .{ .calz = 20000, .gapz = 400 };
pub const Pt = struct { x: f64, y: f64 };
pub const Node = struct { role: []const u8, name: []const u8, valu: []const u8, bid: i64 };
fn strOf(val: ?std.json.Value) []const u8 { const vzz = val orelse return ""; if (vzz != .object) return ""; const inn = vzz.object.get("value") orelse return ""; return if (inn == .string) inn.string else ""; }
pub fn numF(val: std.json.Value) f64 { return switch (val) { .integer => |num| @floatFromInt(num), .float => |num| num, else => 0 }; }
pub fn parseAx(aren: std.mem.Allocator, result: std.json.Value) ![]Node { if (result != .object) return error.CdpError; const arr = result.object.get("nodes") orelse return error.CdpError; if (arr != .array) return error.CdpError; var out: std.ArrayList(Node) = .empty; for (arr.array.items) |item| { if (item != .object) continue; if (item.object.get("ignored")) |ign| { if (ign == .bool and ign.bool) continue; } const bidv = item.object.get("backendDOMNodeId") orelse continue; if (bidv != .integer) continue; try out.append(aren, .{ .role = strOf(item.object.get("role")), .name = strOf(item.object.get("name")), .valu = strOf(item.object.get("value")), .bid = bidv.integer }); } return out.items; }
pub fn axSnap(aren: std.mem.Allocator, conn: *cdp.Conn) ![]Node { _ = try conn.callJson(aren, "Accessibility.enable", "", CF.calz); const res = try conn.callJson(aren, "Accessibility.getFullAXTree", "", CF.calz); return parseAx(aren, res); }
fn hasSub(hay: []const u8, nee: []const u8) bool { if (nee.len == 0) return true; return std.ascii.findIgnoreCase(hay, nee) != null; }
pub fn findNode(nodes: []const Node, role: []const u8, name: []const u8) ?Node { if (name.len > 0) { for (nodes) |nod| { if (role.len > 0 and !std.ascii.eqlIgnoreCase(nod.role, role)) continue; if (std.ascii.eqlIgnoreCase(nod.name, name)) return nod; } } for (nodes) |nod| { if (role.len > 0 and !std.ascii.eqlIgnoreCase(nod.role, role)) continue; if (name.len > 0 and !hasSub(nod.name, name)) continue; return nod; } return null; }
pub fn findAll(aren: std.mem.Allocator, nodes: []const Node, role: []const u8, name: []const u8) ![]Node { var out: std.ArrayList(Node) = .empty; for (nodes) |nod| { if (role.len > 0 and !std.ascii.eqlIgnoreCase(nod.role, role)) continue; if (name.len > 0 and !hasSub(nod.name, name)) continue; try out.append(aren, nod); } return out.items; }
pub fn waitFind(aren: std.mem.Allocator, conn: *cdp.Conn, role: []const u8, name: []const u8, tries: u32) !Node { var cnt: u32 = 0; while (cnt < tries) : (cnt += 1) { const nodes = try axSnap(aren, conn); if (findNode(nodes, role, name)) |nod| return nod; std.Io.sleep(conn.iozz, .fromMilliseconds(CF.gapz), .awake) catch {}; } return error.NoElem; }
pub fn evalStr(aren: std.mem.Allocator, conn: *cdp.Conn, js: []const u8) ![]const u8 { const quo = try std.json.Stringify.valueAlloc(aren, js, .{}); const par = try std.fmt.allocPrint(aren, "{{\"expression\":{s},\"returnByValue\":true}}", .{quo}); const res = try conn.callJson(aren, "Runtime.evaluate", par, CF.calz); if (res != .object) return error.CdpError; const rez = res.object.get("result") orelse return error.CdpError; if (rez != .object) return error.CdpError; const val = rez.object.get("value") orelse return ""; return switch (val) { .string => |txt| txt, .integer => |num| try std.fmt.allocPrint(aren, "{d}", .{num}), .bool => |flg| if (flg) "true" else "false", else => "" }; }
pub fn pageTextExcl(aren: std.mem.Allocator, conn: *cdp.Conn, sels: []const []const u8) ![]const u8 { var any = false; for (sels) |sel| { if (sel.len > 0) any = true; } if (!any) return pageText(aren, conn); var arr: std.ArrayList(u8) = .empty; try arr.append(aren, '['); var first = true; for (sels) |sel| { if (sel.len == 0) continue; if (!first) try arr.append(aren, ','); first = false; try arr.appendSlice(aren, try std.json.Stringify.valueAlloc(aren, sel, .{})); } try arr.append(aren, ']'); const js = try std.fmt.allocPrint(aren, "(function(){{var b=document.body.cloneNode(true);{s}.forEach(function(s){{b.querySelectorAll(s).forEach(function(e){{e.remove()}})}});b.querySelectorAll('script,style,noscript,template').forEach(function(e){{e.remove()}});return b.textContent}})()", .{arr.items}); return evalStr(aren, conn, js); }
pub fn pageText(aren: std.mem.Allocator, conn: *cdp.Conn) ![]const u8 { return evalStr(aren, conn, "document.body ? document.body.innerText : ''"); }
pub fn boxCenter(aren: std.mem.Allocator, conn: *cdp.Conn, bid: i64) !Pt { const par = try std.fmt.allocPrint(aren, "{{\"backendNodeId\":{d}}}", .{bid}); _ = conn.callJson(aren, "DOM.scrollIntoViewIfNeeded", par, CF.calz) catch {}; const res = try conn.callJson(aren, "DOM.getBoxModel", par, CF.calz); if (res != .object) return error.CdpError; const mod = res.object.get("model") orelse return error.CdpError; if (mod != .object) return error.CdpError; const con = mod.object.get("content") orelse return error.CdpError; if (con != .array or con.array.items.len < 8) return error.CdpError; var sx: f64 = 0; var sy: f64 = 0; var idx: usize = 0; while (idx < 8) : (idx += 2) { sx += numF(con.array.items[idx]); sy += numF(con.array.items[idx + 1]); } return .{ .x = sx / 4.0, .y = sy / 4.0 }; }
pub fn navigate(aren: std.mem.Allocator, conn: *cdp.Conn, url: []const u8, mill: u32) !void { _ = try conn.callJson(aren, "Page.enable", "", CF.calz); var from = conn.evts.items.len; const quo = try std.json.Stringify.valueAlloc(aren, url, .{}); const par = try std.fmt.allocPrint(aren, "{{\"url\":{s}}}", .{quo}); _ = try conn.callJson(aren, "Page.navigate", par, CF.calz); if (try conn.evWait(aren, "Page.loadEventFired", &from, mill) == null) return error.Timeout; }
